// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address payer, uint256 amount) public {
        vm.assume(payer != address(0));
        amount = bound(amount, 1, 1 ether);

        GoodReceiver good = new GoodReceiver();

        vm.deal(payer, amount);
        vm.prank(payer);
        (bool sent,) = address(c).call{value: amount}("");
        require(sent, "funding c failed in test setup");

        bool ok;
        try c.sendMoney(address(good), amount, "") {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract GoodReceiver {
    fallback() external payable {}
    receive() external payable {}
}
